import { ValidScraperRoleRule } from './cloudIamAuthorizer.js';
import { IAMClient, CreateRoleCommand, PutRolePolicyCommand } from '@aws-sdk/client-iam';
import { STSClient, GetCallerIdentityCommand } from '@aws-sdk/client-sts';

/**
 * These tests exercise the scraper-role verification against the local
 * AWS-compatible emulator configured through AWS_ENDPOINT_URL.
 */
const GOOD_ROLE = 'arn:aws:iam::600000000042:role/spec-scraper-good';
const NOPERM_ROLE = 'arn:aws:iam::600000000042:role/spec-scraper-noperm';
const EXTERNAL_ID = 'spec-good-ext';

const trustPolicy = (principalArn: string, externalId: string) =>
    JSON.stringify({
        Version: '2012-10-17',
        Statement: [
            {
                Effect: 'Allow',
                Principal: { AWS: principalArn },
                Action: 'sts:AssumeRole',
                Condition: { StringEquals: { 'sts:ExternalId': externalId } },
            },
        ],
    });

describe('ValidScraperRoleRule (against local AWS emulator)', () => {
    const rule = new ValidScraperRoleRule();
    const args = {} as any;

    beforeAll(async () => {
        const sts = new STSClient({});
        const { Arn } = await sts.send(new GetCallerIdentityCommand({}));
        const accountRoot = `arn:aws:iam::${Arn.split(':')[4]}:root`;
        const iam = new IAMClient({});

        const ensureRole = async (name: string, externalId: string, withEc2Read: boolean) => {
            try {
                await iam.send(
                    new CreateRoleCommand({
                        RoleName: name,
                        AssumeRolePolicyDocument: trustPolicy(accountRoot, externalId),
                    }),
                );
            } catch (e) {
                if (e?.name !== 'EntityAlreadyExists') throw e;
            }
            if (withEc2Read) {
                await iam.send(
                    new PutRolePolicyCommand({
                        RoleName: name,
                        PolicyName: 'ec2read',
                        PolicyDocument: JSON.stringify({
                            Version: '2012-10-17',
                            Statement: [{ Effect: 'Allow', Action: ['ec2:Describe*'], Resource: '*' }],
                        }),
                    }),
                );
            }
        };

        await ensureRole('spec-scraper-good', EXTERNAL_ID, true);
        await ensureRole('spec-scraper-noperm', EXTERNAL_ID, false);
    });

    test('undefined cloudIAM: nothing to prove, valid', async () => {
        await expect(rule.validate(undefined as any, args)).resolves.toBe(true);
    });

    test('blank role: disconnect, valid', async () => {
        await expect(rule.validate({ iamRoleArn: '' } as any, args)).resolves.toBe(true);
        await expect(rule.validate({ iamRoleArn: '   ' } as any, args)).resolves.toBe(true);
    });

    test('names no role: invalid rather than a disconnect', async () => {
        await expect(rule.validate({ externalId: 'foo' } as any, args)).resolves.toBe(false);
        await expect(rule.validate({} as any, args)).resolves.toBe(false);
    });

    test('unassumable role: invalid', async () => {
        await expect(
            rule.validate({ iamRoleArn: 'wow a fake role', externalId: 'foobar' } as any, args),
        ).resolves.toBe(false);
    });

    test('wrong external id: invalid', async () => {
        await expect(rule.validate({ iamRoleArn: GOOD_ROLE, externalId: 'wrong' } as any, args)).resolves.toBe(
            false,
        );
    });

    test('assumable role that cannot read the instance inventory: invalid', async () => {
        await expect(
            rule.validate({ iamRoleArn: NOPERM_ROLE, externalId: EXTERNAL_ID } as any, args),
        ).resolves.toBe(false);
    });

    test('assumable role that can read the instance inventory: valid', async () => {
        await expect(
            rule.validate({ iamRoleArn: GOOD_ROLE, externalId: EXTERNAL_ID } as any, args),
        ).resolves.toBe(true);
    });

    test('message mentions IAM', () => {
        expect(rule.defaultMessage(args)).toEqual(expect.stringContaining('IAM'));
    });
});
