import { Injectable, Logger } from '@nestjs/common';
import {
    ValidationOptions,
    registerDecorator,
    ValidationArguments,
    ValidatorConstraintInterface,
    ValidatorConstraint,
} from 'class-validator';
import { STSClient, AssumeRoleCommand } from '@aws-sdk/client-sts';
import { getInstanceWithFilters } from '../../utils/aws/awsEc2.js';
import { CloudIAM } from './update-settings.dto.js';

/**
 * Validates a customer's scraper role before it is saved.
 *
 * Two things must be true for a named role to be accepted:
 *   1. The role can be assumed with the supplied external id.
 *   2. The credentials returned from assuming the role can read the
 *      instance inventory used by collection (EC2 DescribeInstances).
 *
...
@ValidatorConstraint({ name: 'ValidScraperRoleRule', async: true })
@Injectable()
export class ValidScraperRoleRule implements ValidatorConstraintInterface {
    private static readonly logger = new Logger(ValidScraperRoleRule.name);

    async validate(cloudIAM: CloudIAM, _args: ValidationArguments): Promise<boolean> {
        try {
            // Nothing supplied for the scraper role, nothing to prove.
            if (!cloudIAM) {
                return true;
            }

            const { iamRoleArn, externalId } = cloudIAM;

            // A settings block that names no role is invalid rather than a disconnect.
            if (iamRoleArn === undefined || iamRoleArn === null || typeof iamRoleArn !== 'string') {
                return false;
            }

            // A blank role means disconnect; the service clears the external id.
            if (iamRoleArn.trim() === '') {
                return true;
            }

            const region = process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1';

            // 1. Prove the role can be assumed with the supplied external id.
            const sts = new STSClient({ region });
            const assumed = await sts.send(
                new AssumeRoleCommand({
                    RoleArn: iamRoleArn,
                    ExternalId: externalId ? externalId : undefined,
                    RoleSessionName: 'meteringco-scraper-role-verification',
                }),
            );

            const credentials = assumed?.Credentials;
            if (!credentials?.AccessKeyId || !credentials?.SecretAccessKey) {
                return false;
            }

            const creds = {
                accessKeyId: credentials.AccessKeyId,
                secretAccessKey: credentials.SecretAccessKey,
                sessionToken: credentials.SessionToken,
            };

            // 2. Prove the returned credentials can read the instance inventory used by collection.
            await getInstanceWithFilters(region, creds);

            return true;
        } catch (e) {
            ValidScraperRoleRule.logger.error(`Failed to verify scraper role: ${e?.name ?? ''} ${e?.message ?? e}`);
            return false;
        }
    }

    defaultMessage(_args: ValidationArguments) {
        return 'Unable to assume the provided IAM role with the supplied external ID, or the assumed credentials cannot read the instance inventory. Please double check the IAM role ARN and external ID.';
    }
}
"
}

